--
-- Table structure for table `especies_especie`
--

DROP TABLE IF EXISTS `especies_especie`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `especies_especie` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `nombre_comun` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_cientifico` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado_conservacion` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `diametro_maximo` decimal(5,2) DEFAULT NULL,
  `altura_maxima` decimal(4,2) DEFAULT NULL,
  `descripcion` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `creador_id` bigint NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `diametro_campus` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nombre_cientifico` (`nombre_cientifico`),
  UNIQUE KEY `slug` (`slug`),
  KEY `especies_especie_creador_id_f9d431e6_fk_perfiles_usuario_id` (`creador_id`),
  KEY `especies_especie_nombre_comun_b66e49bc` (`nombre_comun`),
  CONSTRAINT `especies_especie_creador_id_f9d431e6_fk_perfiles_usuario_id` FOREIGN KEY (`creador_id`) REFERENCES `perfiles_usuario` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
