  `frutos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `semillas` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `biogeografia` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
