  PRIMARY KEY (`id`),
  KEY `especies_galeria_autor_id_2c4aaeb1_fk_perfiles_usuario_id` (`autor_id`),
  KEY `especies_galeria_especie_id_a85fc3a0_fk_especies_especie_id` (`especie_id`),
  CONSTRAINT `especies_galeria_autor_id_2c4aaeb1_fk_perfiles_usuario_id` FOREIGN KEY (`autor_id`) REFERENCES `perfiles_usuario` (`id`),
  CONSTRAINT `especies_galeria_especie_id_a85fc3a0_fk_especies_especie_id` FOREIGN KEY (`especie_id`) REFERENCES `especies_especie` (`id`)
