DROP TABLE IF EXISTS `mapa_inventario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mapa_inventario` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cantidad` int unsigned NOT NULL,
  `especie_id` bigint NOT NULL,
  `zona_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `mapa_inventario_zona_id_especie_id_e455822b_uniq` (`zona_id`,`especie_id`),
  KEY `mapa_inventario_especie_id_eafbfdbb_fk_especies_especie_id` (`especie_id`),
  CONSTRAINT `mapa_inventario_especie_id_eafbfdbb_fk_especies_especie_id` FOREIGN KEY (`especie_id`) REFERENCES `especies_especie` (`id`),
  CONSTRAINT `mapa_inventario_zona_id_54337898_fk_mapa_zona_id` FOREIGN KEY (`zona_id`) REFERENCES `mapa_zona` (`id`),
  CONSTRAINT `mapa_inventario_chk_1` CHECK ((`cantidad` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=982 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
